import java.util.*;
import java.io.*;

public class Main {
    static class Edge {
        int to, capacity, flow, cost;
        public Edge(int to, int capacity, int flow, int cost) {
            this.to = to;
            this.capacity = capacity;
            this.flow = flow;
            this.cost = cost;
        }
    }

    static final int MAXNODES = 15000;
    static List<Edge> edges_list = new ArrayList<>();
    static List<Integer>[] adj_list = new ArrayList[MAXNODES];
    static long total_cost = 0;
    static long[] dist_array = new long[MAXNODES];
    static int[] parent = new int[MAXNODES];
    static int[] parent_edge = new int[MAXNODES];
    static int[] in_queue = new int[MAXNODES];

    static int n, m, k, c, d;
    static int source = 9998;
    static int sink = 9999;
    static int current_node;

    public static void addEdge(int u, int v, int cap, int cst) {
        adj_list[u].add(edges_list.size());
        edges_list.add(new Edge(v, cap, 0, cst));
        adj_list[v].add(edges_list.size());
        edges_list.add(new Edge(u, 0, 0, -cst));
    }

    public static void runFlow() {
        Arrays.fill(dist_array, Long.MAX_VALUE);
        Arrays.fill(parent, -1);
        Arrays.fill(parent_edge, -1);
        Arrays.fill(in_queue, 0);
        dist_array[source] = 0;
        Queue<Integer> q = new LinkedList<>();
        q.offer(source);
        in_queue[source] = 1;
        current_node = sink;

        while (!q.isEmpty()) {
            int u = q.poll();
            in_queue[u] = 0;
            for (int e_idx : adj_list[u]) {
                Edge e = edges_list.get(e_idx);
                if (e.capacity - e.flow == 0) continue;
                int cst = e.cost;
                int y = e.to;
                if (dist_array[y] > dist_array[u] + cst) {
                    dist_array[y] = dist_array[u] + cst;
                    parent[y] = u;
                    parent_edge[y] = e_idx;
                    if (in_queue[y] == 0) {
                        in_queue[y] = 1;
                        q.offer(y);
                    }
                }
            }
        }

        int node = current_node;
        while (node != source) {
            int e_idx = parent_edge[node];
            edges_list.get(e_idx).flow++;
            edges_list.get(e_idx ^ 1).flow--;
            node = parent[node];
        }
        total_cost += dist_array[sink];
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        m = Integer.parseInt(st.nextToken());
        k = Integer.parseInt(st.nextToken());
        c = Integer.parseInt(st.nextToken());
        d = Integer.parseInt(st.nextToken());

        for (int i = 0; i < MAXNODES; i++) {
            adj_list[i] = new ArrayList<>();
        }

        for (int i = 1; i <= k; i++) {
            int x = Integer.parseInt(br.readLine());
            x--;
            addEdge(source, x, 1, 0);
        }

        for (int i = 1; i <= 101; i++) {
            addEdge((i - 1) * n, sink, k, (i - 1) * c);
        }

        for (int i = 0; i < m; i++) {
            st = new StringTokenizer(br.readLine());
            int x = Integer.parseInt(st.nextToken());
            int y = Integer.parseInt(st.nextToken());
            x--;
            y--;
            for (int i_i = 1; i_i <= 100; i_i++) {
                for (int j = 1; j <= k; j++) {
                    addEdge(x + (i_i - 1) * n, y + (i_i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                    addEdge(y + (i_i - 1) * n, x + (i_i - 1) * n + n, 1, d * ((j - 1) * 2 + 1));
                }
            }
        }

        for (int i_i = 1; i_i <= n; i_i++) {
            for (int j = 1; j <= 100; j++) {
                addEdge(i_i - 1 + (j - 1) * n, i_i - 1 + (j - 1) * n + n, k, 0);
            }
        }

        for (int i_i = 1; i_i <= k; i_i++) {
            runFlow();
        }

        System.out.println(total_cost);
    }
}
